```
pad nums with 1 at both ends → arr of size n+2
for len = 2 to n+1:
    for i = 0 to n+1-len:
        j = i + len
        for k = i+1 to j-1:
            dp[i][j] = max(dp[i][j], arr[i]*arr[k]*arr[j] + dp[i][k] + dp[k][j])
return dp[0][n+1]
```

code.cpp:
class Solution {
public:
    int maxCoins(vector<int>& nums) {
        int n = nums.size();
        vector<int> arr(n + 2);
        arr[0] = 1;
        arr[n + 1] = 1;
        for (int i = 0; i < n; i++) arr[i + 1] = nums[i];
        int m = n + 2;
        vector<vector<long long>> dp(m, vector<long long>(m, 0));
        for (int len = 2; len <= m - 1; len++) {
            for (int i = 0; i + len < m; i++) {
                int j = i + len;
                for (int k = i + 1; k < j; k++) {
                    long long val = (long long)arr[i] * arr[k] * arr[j]
                                 + dp[i][k] + dp[k][j];
                    if (val > dp[i][j]) dp[i][j] = val;
                }
            }
        }
        return (int)dp[0][m - 1];
    }
};
